+    // Only stop showing the actions once the popup has finished triggering the chosen one.
+    QTimer::singleShot(0, this, [this] {
+        if (m_popup && !m_popup->isVisible()) {
+            setSourceMenu(nullptr);
+        }
+    });
+}
+
+void AppMenuApplet::setSourceMenu(QMenu *menu)
+{
+    if (m_sourceMenu == menu) {
+        return;
+    }
+    if (m_sourceMenu) {
+        m_sourceMenu->removeEventFilter(this);
+    }
+    for (QAction *action : m_popup->actions()) {
+        m_popup->removeAction(action);
+    }
+    m_sourceMenu = menu;
+    if (m_sourceMenu) {
+        // The actions stay in the app's menu too, so the app and the search can keep updating it.
+        // eventFilter() follows those changes.
+        m_popup->addActions(m_sourceMenu->actions());
+        m_sourceMenu->installEventFilter(this);
+    }
 }

