+// The Global Menu shows the Search menu's actions in its own popup, so the search field is created for each
+// menu showing it instead of being one default widget. Closing the field ends the search.
+class SearchFieldAction : public QWidgetAction
+{
+public:
+    explicit SearchFieldAction(AppMenuModel *model)
+        : QWidgetAction(model)
+        , m_model(model)
+    {
+    }
+
+protected:
+    QWidget *createWidget(QWidget *parent) override
+    {
+        return m_model->createSearchBar(parent);
+    }
+
+    void deleteWidget(QWidget *widget) override
+    {
+        m_model->removeSearchActionsFromMenu();
+        QWidgetAction::deleteWidget(widget);
+    }
+
+private:
+    AppMenuModel *const m_model;
+};
